def duration(start: int, end: int) -> int:
    """Return the duration between integer minute marks."""
    if end <= start:
        raise ValueError("end must be greater than start")
    return end - start

import pytest
from src import duration


def test_valid_interval_keeps_its_duration():
    assert duration(10, 60) == 50


def test_equal_marks_raise_value_error():
    with pytest.raises(ValueError):
        duration(30, 30)


def test_reversed_marks_raise_value_error():
    with pytest.raises(ValueError):
        duration(50, 20)
